import {Config} from 'alinea'
import {Home, Settings} from './schema'

export const pages = Config.root('Pages', {
  contains: ['Page', 'Blog'],
  i18n: {locales: ['en', 'fr']},
  children: {
    index: Config.page({type: Home, fields: {title: 'Home'}})
  }
})

export const settings = Config.root('Settings', {
  contains: [],
  children: {
    settings: Config.page({type: Settings, fields: {title: 'Site settings'}})
  }
})

import {Config} from 'alinea'
import {Blog, Home} from './schema'

export const pages = Config.root('Pages', {
  contains: ['Page'],
  children: {
    // The key is the path: "index" becomes the home page at /
    index: Config.page({type: Home, fields: {title: 'Home'}}),
    blog: Config.page({type: Blog, fields: {title: 'Blog'}})
  }
})

import {Config} from 'alinea'

export const pages = Config.root('Pages', {
  contains: ['Page'],
  i18n: {locales: ['en', 'fr', 'nl']}
})

import {cms} from '@/cms'
import {Query} from 'alinea'

const navigation = await cms.find({
  root: cms.workspaces.main.pages,
  locale: 'en',
  level: 0,
  select: {title: Query.title, url: Query.url}
})
